        fr: "Anas (qu'Allah l'agrée) rapporte : « Un Bédouin vint et urina dans un coin de la mosquée. Les gens le réprimandèrent bruyamment, mais le Prophète ﷺ les en empêcha. Lorsqu'il eut terminé de soulager son besoin, le Prophète ﷺ ordonna qu'on verse un seau d'eau dessus. »",
        src: "Bukhari & Muslim",
        nar: "Anas ibn Malik",
        cat: 'bulugh',
        subcat: 'tahara',
        commentaryFr: `**Commentaire (Sharh) - Cheikh Al-Fawzân :**
1. **Sagesse dans la prédication (Da'wah) :** Le Prophète ﷺ a fait preuve d'une immense sagesse en arrêtant les compagnons. Si l'homme avait été interrompu brutalement, il aurait pu se faire du mal, ou salir ses vêtements et une plus grande surface de la mosquée en s'enfuyant.
2. **Purification de la terre :** Ce hadith établit une règle de jurisprudence (Fiqh) : la terre ou le sol souillé par une impureté liquide (comme l'urine) se purifie simplement en y versant de l'eau en quantité suffisante, sans avoir besoin de retirer ou de creuser la terre.
3. **L'ignorance excuse :** Le Bédouin a agi par ignorance des bienséances liées aux mosquées, d'où la douceur de l'enseignement prophétique à son égard.

*(Source : Al-Minhat al-Rabbaniyyah fi Sharh Bulugh al-Maram ou Tas-hil al-Ilmam)*`
