        fr: "« Cinq pratiques font partie de la saine nature (Fitrah) : la circoncision, le rasage des poils pubiens, la taille des moustaches, la coupe des ongles et l'épilation des aisselles. »",
        src: "Bukhari & Muslim",
        nar: "Aisha",
        cat: 'bulugh',
